  prisma.user.findMany({ select: { id: true, name: true } }),
  prisma.post.groupBy({
    by: ['authorId'],
    _count: { id: true },
  }),
  prisma.comment.groupBy({
    by: ['authorId'],
    _count: { id: true },
  }),
]);

const postCountMap = new Map(postCounts.map(p => [p.authorId, p._count.id]));
const commentCountMap = new Map(commentCounts.map(c => [c.authorId, c._count.id]));

const stats = users.map(user => ({
  user: user.name,
  postCount: postCountMap.get(user.id) ?? 0,
  commentCount: commentCountMap.get(user.id) ?? 0,
}));

