Remove `InsecureSkipVerify: true`. The default Go TLS configuration performs full certificate verification and is secure out of the box. If you need to trust a custom CA (e.g., for internal services), configure a custom `RootCAs` pool instead.

```go
package main

import (
    "io/ioutil"
    "net/http"
)

func fetchData(url string) ([]byte, error) {
    // Default http.Client already validates TLS certificates
    resp, err := http.Get(url)
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()
    return ioutil.ReadAll(resp.Body)
