import (
    "errors"
    "net"
    "net/url"
)

func validateURL(raw string) error {
    u, err := url.Parse(raw)
    if err != nil {
        return err
    }
    if u.Scheme != "https" {
        return errors.New("only HTTPS URLs are permitted")
    }
    host := u.Hostname()
    ip := net.ParseIP(host)
    if ip != nil && (ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast()) {
        return errors.New("requests to internal addresses are not permitted")
    }
    return nil
}
